  for(var entry:Map.of(1,"OWNER",2,"MANAGER",3,"ACCOUNTANT",4,"ACCOUNTANT",5,"TENANT",6,"TECHNICIAN",7,"OWNER",8,"TENANT",9,"TECHNICIAN").entrySet())f.db.sql("INSERT INTO user_roles(user_id,role_id) SELECT :id,id FROM roles WHERE code=:role").param("id",entry.getKey()).param("role",entry.getValue()).update();
