  f.db.sql("INSERT INTO tenant_residences(tenant_profile_id,property_id,room_id,contract_id,residence_role,status,move_in_date) VALUES(:profile,:property,:room,:contract,'REPRESENTATIVE','ACTIVE',CURRENT_DATE)").param("profile",profileB).param("property",propertyB).param("room",roomB).param("contract",contractB).update();
  invoiceB=f.inTx(()->b.invoiceService.create(ownerB,new SaveInvoice(roomB,contractB,LocalDate.now().toString().substring(0,7),LocalDate.now().withDayOfMonth(1),LocalDate.now().withDayOfMonth(1).plusMonths(1).minusDays(1),LocalDate.now(),LocalDate.now().plusDays(7),List.of(new AdditionalItem("Synthetic obligation",BigDecimal.ONE,"item",n("800000"),"Agreed")),BigDecimal.ZERO,false,null,"ISSUE",null)).id());
