  f.db.sql("INSERT INTO tenant_documents(tenant_profile_id,property_id,document_type,original_name,content_type,file_size,file_content,uploaded_by) VALUES(:profile,:property,'OTHER','synthetic.pdf','application/pdf',4,:bytes,1)").param("profile",a.profile()).param("property",a.property()).param("bytes",new byte[]{1,2,3,4}).update();document=f.db.sql("SELECT MAX(id) FROM tenant_documents").query(Long.class).single();
