 @Test void successfulLoginRetiresThePreviousBearerFamily()throws Exception{String old=token(5,RoleCode.TENANT);mvc.perform(post("/api/auth/login").header("Authorization","Bearer "+old).contentType(MediaType.APPLICATION_JSON).content("{\"email\":\"p03-5@test.invalid\",\"password\":\"Test-Password-123\",\"requestedRole\":\"TENANT\"}")).andExpect(status().isOk());mvc.perform(get("/api/auth/me").header("Authorization","Bearer "+old)).andExpect(status().isUnauthorized());}
 @Test void financeReportRequiresRoleAndCurrentPropertyScope()throws Exception{String query="?propertyId="+a.property()+"&startDate="+LocalDate.now().withDayOfMonth(1)+"&endDate="+LocalDate.now();getAs(1,RoleCode.OWNER,"/api/admin/finance"+query).andExpect(status().isOk()).andExpect(jsonPath("$.data.accountingProfitSupported").value(false));getAs(5,RoleCode.TENANT,"/api/admin/finance"+query).andExpect(status().isForbidden());getAs(3,RoleCode.ACCOUNTANT,"/api/accountant/finance?propertyId="+propertyB+"&startDate="+LocalDate.now()+"&endDate="+LocalDate.now()).andExpect(status().isForbidden());}
