 String propertyEdit(Long manager){var row=f.db.sql("SELECT * FROM properties WHERE id=:id").param("id",a.property()).query().singleRow();var body=new LinkedHashMap<String,Object>();body.put("code",row.get("code"));body.put("name","Synthetic edited property");body.put("type","BOARDING_HOUSE");body.put("address","Synthetic test address");body.put("version",row.get("version"));if(manager!=null)body.put("managerId",manager);return new tools.jackson.databind.ObjectMapper().writeValueAsString(body);}
 @Test void managerCannotReassignPropertyThroughOrdinaryEditor()throws Exception{mvc.perform(put("/api/admin/properties/"+a.property()).header("Authorization","Bearer "+token(2,RoleCode.MANAGER)).contentType(MediaType.APPLICATION_JSON).content(propertyEdit(6L))).andExpect(status().isForbidden());assertThat(f.db.sql("SELECT COUNT(*) FROM manager_property_capabilities WHERE property_id=:id AND manager_id=2").param("id",a.property()).query(Long.class).single()).isEqualTo(5);}
