 @Test void maintenanceCsvRequiresExportCapabilityAndNeutralizesFormulas(){f.db.sql("UPDATE maintenance_requests SET title='=SUM(1,2)' WHERE id=:id").param("id",task).update();var service=new com.thangit.boardinghouse.service.impl.AdminMaintenanceServiceImpl(new AdminMaintenanceRepository(f.db,new RoomLifecycleGuard(f.db)));String csv=new String(service.export(f.owner,a.property(),null),java.nio.charset.StandardCharsets.UTF_8);assertThat(csv).contains("'=SUM(1,2)");access.assignManager(f.owner,a.property(),new PropertyAuthorization.ManagerAssignment(2L,Set.of(PropertyAuthorization.Capability.FINANCE_READ),"No export"));assertThatThrownBy(()->service.export(new AuthenticatedUser(2L,"manager",RoleCode.MANAGER),a.property(),null)).isInstanceOf(com.thangit.boardinghouse.common.exception.AuthException.class);}
