 @Test void initialMeterInstallationHasScopeStateAndIdempotencyGuards()throws Exception{String body="{\"type\":\"ELECTRICITY\",\"code\":\"QA-E\",\"reading\":0,\"reference\":\"QA installation evidence\",\"reason\":\"Initial installation\"}";mvc.perform(post("/api/admin/rooms/"+roomB+"/meters").header("Authorization","Bearer "+token(1,RoleCode.OWNER)).contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isForbidden());mvc.perform(post("/api/admin/rooms/"+a.room()+"/meters").header("Authorization","Bearer "+token(5,RoleCode.TENANT)).contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isForbidden());mvc.perform(post("/api/admin/rooms/"+a.room()+"/meters").header("Authorization","Bearer "+token(1,RoleCode.OWNER)).contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isConflict());var empty=f.booking("0");for(int retry=0;retry<2;retry++)mvc.perform(post("/api/admin/rooms/"+empty.room()+"/meters").header("Authorization","Bearer "+token(1,RoleCode.OWNER)).contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isOk());assertThat(f.db.sql("SELECT COUNT(*) FROM utility_meters WHERE room_id=:id").param("id",empty.room()).query(Long.class).single()).isEqualTo(1);}
 @Test void concurrentInitialMeterInstallationCannotCreateTwoActiveMeters()throws Exception{var empty=f.booking("0");String signed=token(1,RoleCode.OWNER);var gate=new java.util.concurrent.CountDownLatch(1);try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var jobs=new ArrayList<java.util.concurrent.Future<Integer>>();for(int i=0;i<2;i++){final int number=i;jobs.add(pool.submit(()->{gate.await();return mvc.perform(post("/api/admin/rooms/"+empty.room()+"/meters").header("Authorization","Bearer "+signed).contentType(MediaType.APPLICATION_JSON).content("{\"type\":\"WATER\",\"code\":\"QA-W-"+number+"\",\"reading\":0,\"reference\":\"QA evidence\",\"reason\":\"Initial install\"}")).andReturn().getResponse().getStatus();}));}gate.countDown();var statuses=new ArrayList<Integer>();for(var job:jobs)statuses.add(job.get(15,java.util.concurrent.TimeUnit.SECONDS));assertThat(statuses).containsExactlyInAnyOrder(200,409);}assertThat(f.db.sql("SELECT COUNT(*) FROM utility_meters WHERE room_id=:id AND status='ACTIVE'").param("id",empty.room()).query(Long.class).single()).isEqualTo(1);}
