 @Test void profileChildrenDoNotLeakAnotherOwnersOldInvoice(){var repo=new AdminTenantRepository(f.db,new RoomLifecycleGuard(f.db));long foreign=f.insert("INSERT INTO contracts(room_id,tenant_id,tenant_profile_id,code,start_date,end_date,agreed_monthly_rent,status) VALUES("+roomB+",5,"+a.profile()+",'SHARED-OLD',CURRENT_DATE,DATE_ADD(CURRENT_DATE,INTERVAL 1 YEAR),0,'TERMINATED')");assertThat(repo.contracts(a.profile(),1,RoleCode.OWNER)).noneMatch(row->row.id()==foreign);var allowed=f.db.sql("SELECT id FROM properties WHERE owner_id=1").query(Long.class).list();assertThat(repo.residences(a.profile(),1,RoleCode.OWNER)).allMatch(row->allowed.contains(row.propertyId()));}
