 @Test void tc31_paymentAndReversalSynchronizeTenantOwnerAndAccountant()throws Exception{var lease=b.active("0",false);long invoice=b.oldDebt(lease,"500000");var result=mvc.perform(post("/api/accountant/payments").header("Authorization","Bearer "+token(3,RoleCode.ACCOUNTANT)).header("Idempotency-Key",UUID.randomUUID().toString()).contentType(MediaType.APPLICATION_JSON).content("{\"invoiceId\":"+invoice+",\"amount\":500000,\"paymentMethod\":\"CASH\",\"paidAt\":\""+LocalDateTime.now().minusSeconds(1)+"\",\"issueReceipt\":true}")).andExpect(status().isCreated()).andReturn();long payment=f.db.sql("SELECT id FROM payments WHERE invoice_id=:id AND status='CONFIRMED'").param("id",invoice).query(Long.class).single();getAs(5,RoleCode.TENANT,"/api/tenant/invoices/"+invoice).andExpect(status().isOk()).andExpect(jsonPath("$.data.remainingAmount").value(0));var dashboard=new DashboardRepository(f.db);LocalDate month=LocalDate.now().withDayOfMonth(1);assertThat((BigDecimal)dashboard.summary(1L,RoleCode.OWNER,lease.property(),month,month.plusMonths(1),month.minusMonths(1)).get("currentRevenue")).isEqualByComparingTo("500000");assertThat(f.accounting.outstandingDebt(3,lease.property())).isZero();mvc.perform(post("/api/accountant/payments/"+payment+"/reverse").header("Authorization","Bearer "+token(3,RoleCode.ACCOUNTANT)).contentType(MediaType.APPLICATION_JSON).content("{\"version\":0,\"reason\":\"Synthetic reversal verified\"}")).andExpect(status().isOk());getAs(5,RoleCode.TENANT,"/api/tenant/invoices/"+invoice).andExpect(status().isOk()).andExpect(jsonPath("$.data.remainingAmount").value(500000));assertThat(f.accounting.outstandingDebt(3,lease.property())).isEqualByComparingTo("500000");assertThat((BigDecimal)dashboard.summary(1L,RoleCode.OWNER,lease.property(),month,month.plusMonths(1),month.minusMonths(1)).get("currentRevenue")).isZero();}
 @Test void cashChartUsesPaymentDateInsteadOfInvoiceMonth(){var lease=b.active("0",false);LocalDate month=LocalDate.now().withDayOfMonth(1);long invoice=b.oldDebt(lease,"500000");f.db.sql("UPDATE invoices SET billing_period=:period WHERE id=:id").param("period",month.minusMonths(1)).param("id",invoice).update();f.run(()->b.invoiceService.payment(f.owner,invoice,UUID.randomUUID().toString(),new RecordPayment(n("500000"),"CASH",LocalDateTime.now().minusSeconds(1),null,"Late payment in current month",null)));var points=new DashboardRepository(f.db).revenueHistory(1L,RoleCode.OWNER,lease.property(),2);assertThat(points).hasSize(2);assertThat(points.stream().filter(p->p.period().equals("%02d/%d".formatted(month.getMonthValue(),month.getYear()))).findFirst().orElseThrow().revenue()).isEqualByComparingTo("500000");}
